  var rootCache = { href: '', url: null };
  function rootOf(href) {
    if (rootCache.href !== href) rootCache = { href: href, url: new URL(href) };
    return rootCache.url;
  }

  /** `s` with its `v` parameter set to `key` (other parameters and the hash kept). */
